@startuml

class SensorController {
}

class Apartment {
  +address : string
  +email : string
}

class Inhabitant {
  +username : string
  +password : string
}

class Room {
  +description : string
}

abstract class Sensor {
  +vendor_id : string
  +description : string
  +unit : Unit
  +threshold : float
}

class TemperatureSensor extends Sensor {
  +min : float
  +max : float
}

class PowerSensor extends Sensor {
  +counter_reading : float
}

class MeasuredValue {
  +timestamp : datetime
  +value : float
}

class EMonitor {
}

enum Unit {
  CELSIUS
  WATT
}

SensorController "1" -- "*" Apartment : manages
SensorController "1" -- "*" Inhabitant : manages
Apartment "1" *-- "2..*" Room : consists of
Room "1" *-- "*" Sensor : contains
Sensor "1" *-- "*" MeasuredValue : records
Sensor "0..1" -- "1" Room : assigned to
Inhabitant "0..1" -- "*" Sensor : configures
EMonitor "1" -- "*" Sensor : checks thresholds
Sensor "1" --> "0..1" MeasuredValue : last value

@enduml

